import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Mobile App Shell","description":"","frontmatter":{"epic":8,"title":"Mobile App Shell","status":"⏳ In Progress","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/mobile-app-shell.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/mobile-app-shell.md","filePath":"sovereign-edge/epics/mobile/mobile-app-shell.md"}'),n={name:"sovereign-edge/epics/mobile/mobile-app-shell.md"};function r(i,e,l,c,p,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="epic-mobile-app-shell" tabindex="-1">Epic: Mobile App Shell <a class="header-anchor" href="#epic-mobile-app-shell" aria-label="Permalink to &quot;Epic: Mobile App Shell&quot;">​</a></h1><blockquote><p>The React Native app itself — iOS and Android, from Phase 1. Not a WebView wrapper around anything; this is the actual product.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Distinct from <code>sovereign-mobile</code> (a planned, unrelated Capacitor shell that just loads a self-hosted <code>sovereign</code> instance in a WebView). Sovereign Edge is a real native app with its own UI, its own on-device inference, and its own connector framework — nothing here is a wrapper around a web app.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-8-1-—-app-scaffold-navigation-and-settings" tabindex="-1">✅ 8.1 — App scaffold, navigation, and settings <a class="header-anchor" href="#✅-8-1-—-app-scaffold-navigation-and-settings" aria-label="Permalink to &quot;✅ 8.1 — App scaffold, navigation, and settings&quot;">​</a></h4><p><strong>Goal:</strong> The screens and navigation structure everything else plugs into.</p><p><strong>Deliverables:</strong></p><ul><li>Chat screen, model manager screen, connector/permission settings screen, general settings.</li><li>Navigation structure shared across iOS and Android (RN navigation library).</li></ul><p><strong>Dependencies:</strong> Task 0.1 (repo scaffold), Design System epic (7.1–7.2).</p><p><strong>Review checklist:</strong></p><ul><li>✅ All core screens (chat, model manager, connector settings) are reachable and functional. Verified on an Android emulator by navigating to each: chat opens by default, Models lists the catalog with per-device fit against the emulator&#39;s real 3.8 GB, Settings changes the theme preference, and Connectors is reached two hops in from Settings. Navigation chrome — header, back affordance, tab bar — follows the theme in both schemes. Covered by tests that navigate rather than assert the route table, since a screen can be registered and still be unreachable.</li></ul><p><strong>Known gaps, deliberate:</strong> the chat screen composes the real components and holds message state but does not call the inference engine — that is task 1.3. The Connectors screen is empty because no connector and no permission model exist yet (tasks 3.1 and 2.2); its empty state states the product&#39;s central claim, which is true today. Tabs are text-only pending an icon set. The appearance section uses three toggles for a mutually exclusive choice, which reads oddly — it wants a radio control the component set does not have yet.</p><hr><h4 id="📋-8-2-—-store-release-setup" tabindex="-1">📋 8.2 — Store release setup <a class="header-anchor" href="#📋-8-2-—-store-release-setup" aria-label="Permalink to &quot;📋 8.2 — Store release setup&quot;">​</a></h4><p><strong>Goal:</strong> Get the app ready for App Store and Play Store submission.</p><p><strong>Deliverables:</strong></p><ul><li>App Store Connect and Google Play Console listings.</li><li>Privacy declarations accurately reflecting the app&#39;s actual network behavior (no telemetry, connector-scoped network access) — this is the app&#39;s core trust claim, so the store-facing privacy labels have to be exactly right, not just marketing copy.</li></ul><p><strong>Dependencies:</strong> Task 8.1, Core Inference &amp; Chat epic, Connector Framework epic.</p><p><strong>Review checklist:</strong></p><ul><li>The App Store &quot;privacy nutrition label&quot; / Play Data Safety form accurately lists every network destination the app can reach and under what condition (i.e., only per granted connector).</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li></ul>',23)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
